#!/bin/bash

# Функция для запуска задач в пакетах по три с ожиданием между пакетами
run_in_packages() {
    local tasks=("$@")
    local package_size=3
    local max_processes=0
    local current_processes=0

    for ((i=0; i<${#tasks[@]}; i+=package_size)); do
        local package=("${tasks[@]:i:package_size}")
        for task in "${package[@]}"; do
            "$task" &
            ((current_processes++))
            max_processes=$((current_processes > max_processes ? current_processes : max_processes))
        done
        wait
        current_processes=0
        sleep 1  # Ожидание между пакетами
    done

    echo "Пик процессов: $max_processes"
    echo "Общий рост процессов: $((max_processes * package_size))"
}

