#!/bin/bash

function base() {
    local slot_pool=(0 1 2)
    local slot_index=0
    local num_slots=${#slot_pool[@]}

    function worker() {
        local slot=$1
        echo "Worker started with slot $slot"
        sleep 5
        echo "Worker finished with slot $slot"
    }

    function start_child() {
        local slot=${slot_pool[$slot_index]}
        echo "Starting child with slot $slot"
        worker $slot &
        local child_pid=$!
        echo "Child PID: $child_pid"
        wait $child_pid
        echo "Child $child_pid finished"
        slot_index=$(( (slot_index + 1) % num_slots ))
    }

    for i in {1..10}; do
        start_child
    done
}

