if [[ $? -ne 0 ]]; then
  echo "Failed to create temporary directory"
  exit 1
fi

# Cleanup function
cleanup() {
  if [[ -d "$temp_dir" ]]; then
    rm -rf "$temp_dir"
  fi
}

# Trap for cleanup on exit
trap cleanup EXIT

# Define a function to run make with a given number of jobs
run_make() {
  local job_limit=$1
  local makefile_path="$temp_dir/Makefile"

  # Create a Makefile with multiple independent targets
  cat <<EOF > "$makefile_path"
all: target1 target2 target3 target4 target5

target1:
	@echo "Building target1"
	@sleep 1

target2:
	@echo "Building target2"
	@sleep 1

target3:
	@echo "Building target3"
	@sleep 1

target4:
	@echo "Building target4"
	@sleep 1

target5:
	@echo "Building target5"
	@sleep 1
EOF

  # Run make with the specified job limit
  make -j "$job_limit" -f "$makefile_path"
}

# Wrapper function to pass the job limit via nameref
wrapper() {
  local job_limit=$1
  local nameref_limit
  nameref_limit=$job_limit
  run_make "$nameref_limit"
}

# Call the wrapper with unlimited jobs
wrapper "-j"

