#!/bin/bash

# Определение бюджета и overhead
BUDGET=128
RESERVE=32
OVERHEAD=10

# Проверка доступного бюджета
if (( BUDGET + RESERVE < OVERHEAD )); then
  echo "Недостаточный бюджет для запуска"
  exit 1
fi

# Определение количества worker
WORKER_COUNT=48

# Определение функции для запуска worker
function run_worker {
  echo "Запуск worker $1"
  sleep 1  # Имитация работы worker
}

# Определение функции для запуска всех worker
function run_all_workers {
  for (( i=1; i<=WORKER_COUNT; i++ )); do
    run_worker $i &
  done
  wait
}

# Определение функции для запуска ограниченного количества worker
function run_limited_workers {
  for (( i=1; i<=4; i++ )); do
    run_worker $i &
  done
  wait
}

# Определение функции для запуска ядра с ограничением worker
function run_core_limited {
  run_limited_workers
}

# Определение функции для запуска ядра с полным количеством worker
function run_core_full {
  run_all_workers
}

# Определение функции для запуска обёртки с ограничением worker
function run_wrapper_limited {
  bash -c "run_core_limited"
}

# Определение функции для запуска обёртки с полным количеством worker
function run_wrapper_full {
