#!/bin/bash

# Evaluation context
evaluation_context="Тот же sandbox и бюджет; четыре worker выполняют тот же объём работ."

# Function to simulate work
simulate_work() {
    sleep 1
}

# Main function to manage workers
manage_workers() {
    local num_workers=$1
    local total_work=48

    for ((i=0; i<num_workers; i++)); do
        {
            for ((j=0; j<total_work/num_workers; j++)); do
                simulate_work
            done
        } &
    done

    wait
}

# Start the contrast scenario
manage_workers 4

bash -c '
    trap "echo 'SIGCHLD received'; wait -n; echo 'Child finished';" SIGCHLD;
    for i in {1..3}; do
        bash -c "sleep 1; echo 'Child $i finished';" &
    done;
    wait;
    echo "All children finished";
'

alias start_contrast='setup_contrast; run_contrast'
alias run_contrast='handle_sigchld_contrast'

setup_contrast() {
    trap handle_sigchld_contrast SIGCHLD
    export MAX_TASKS=3
    export CURRENT_TASKS=0
}

handle_sigchld_contrast() {
    ((CURRENT_TASKS--))
    if ((CURRENT_TASKS < MAX_TASKS)); then
        start_task_contrast
    fi
}

start_task_contrast() {
    ((CURRENT_TASKS++))
    (sleep 1) &
}

